query Query($where: InventoryTransactionWhereInput, $orderBy: [InventoryTransactionOrderByInput!], $first: Int, $after: String) {
  inventoryTransaction(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        destinationQuantity {
          value
          unitId
        }
        sourceQuantity {
          value
          unitId
        }
        destinationInventoryStatus {
          id
          externalId
        }
        destinationLocationId
        destinationLocation {
          facility {
            id
            externalId
          }
        }
        destinationProductStrategyProcessId
        destinationProductStrategyProcess {
          id
          externalId
          productStrategy {
            id
            externalId
            product {
              id
              externalId
            }
          }
        }
        sourceInventoryStatus {
          id
          externalId
        }
        sourceLocationId
        sourceLocation {
          id
          externalId
        }
        sourceProductStrategyProcess {
          id
          externalId
          productStrategy {
            id
            product {
              id
              externalId
            }
          }
        }
        createdAt
      }
    }
  }
}

query ($where: ReceiptWhereInput, $orderBy: [ReceiptOrderByInput!], $first: Int, $after: String, $whereI: IntegrationWhereInput) {
  receipt(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        externalId
        number
        note
        shipper
        receiptAt
        locationId
        location {
          facilityId
          facility {
            id
            externalId
          }
        }
        purchaseOrderId
        purchaseOrder {
          purchaseOrderTypeId
          externalId
        }
        transferOrderId
        transferOrder {
          id
          toFacilityId
        }
        lines {
          edges {
            node {
              id
              externalId
              number
              inventories {
                edges {
                  node {
                    id
                    number
                  }
                }
              }
              quantity {
                value
                unitId
              }
              transferOrderLine {
                transferOrder {
                  toFacilityId
                }
                transferOrderId
                product {
                  id
                  externalId
                }
                id
                number
                transferQuantity {
                  value
                  unitId
                }
              }
              purchaseOrderLine {
                id
                externalId
                number
                quantity {
                  value
                  unitId
                }
                purchaseOrderId
                product {
                  id
                  externalId
                }
                facilityId
                integrationData
              }
            }
          }
        }
      }
    }
  }
  integration(where: $whereI) {
    edges {
      node {
        id
        configurationData
        active
        integrationModels(where: {id: {_eq: "Receipt"}}) {
          edges {
            node {
              id
              active
              outbound
            }
          }
        }
      }
    }
  }
}

