    edges {
      node {
        id
        number
        externalId
        note
        customData
        integrationData
        shipmentStageId
        shipmentTypeId
        salesOrderId
        salesOrder {
          integrationData
          id
          externalId
          lines {
            edges {
              node {
                id
                number
                externalId
                integrationData
              }
            }
          }
        }
        transferOrderId
        transferOrder {
          integrationData
          id
          toFacilityId
          toFacility {
            id
            externalId
          }
          number
          autoReceipt
          externalId
        }
        shipFromFacilityId
        shipFromFacility {
          id
          externalId
        }
        shipmentLines {
          edges {
            node {
        externalId
              stagedQuantity {
                value
                unitId
              }
              loadedQuantity {
                value
                unitId
              }
              transferOrderLineId
              transferOrderLine {
                id
                externalId
              }
              salesOrderLineId
              salesOrderLine {
                id
                externalId
              }
              shippedQuantity {
                value
                unitId
              }
              productId
              product {
                id
                externalId
              }
            }
          }
        }
      }
    }
  }
  integration(where: {id: {_eq: "NetSuite"}}) {
    edges {
      node {
        id
        active
        configurationData
        integrationModels(where: {id: {_eq: "Fulfillment"}}) {
