}

data.transform:
(
  $shp := $state.context.LOCAL.shipment;
  $r := $shp.(
  $status:=$state.context.REQUEST.DATA.status;
  $lines:=$leftOuterJoin(salesOrder.lines.edges.node ,shipmentLines.edges.node, "id", "salesOrderLineId", 'joinedKey', { 'grouped': true } );
  {
          "action": "fulfill",
          "type": "SO",
          "shipStatus": $status,
          "salesOrderId":salesOrder.externalId,
          "lines":[$lines.(
            $id := integrationData.lineid;
            $quantity:= $status = "A" ? joinedKey.stagedQuantity.value:($status = "B"?joinedKey.loadedQuantity.value : joinedKey.shippedQuantity.value);
            {
              "lineId": $id ,
              "locationId": integrationData.location,
              "qty": $coalesce([$quantity,0]), 
              "detail": []
            }
          )]
        });


  {
    "LOCAL": {
    /* merge likely prevents partial shipments from fulfilling  */
      "request":  $isNilOrEmpty($shp.externalId) ? $r :  $merge([$r,{"recordId":$shp.externalId}]) , 
      "time": $now()
    }
  }
)

