data.query:
query Query($where: ProductionAggregationWhereInput, $strategies: ProductStrategyWhereInput,$orderBy: [ProductionAggregationOrderByInput!], $first: Int, $after: String) {
  agg: productionAggregation(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        quantity
        workOrderProcess {
          workOrderProcessBoms {
            edges {
              node {
                componentProduct {
                  code
                  id
                  strategies(where: $strategies) {
                    edges {
                      node {

                        facility {
                          code
                        }
                        strategyProcesses {
                          edges {
                            node {
                              assemblyBoms {
                                edges {
                                  node {
                                    standardUsage
                                    componentProduct {
                                      code
                                      externalId
                                    }
                                  }
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
        workOrder {
          id
          externalId
          facility {
            code
          }
          integrationData
          customData
        }
        components {
          edges {
            node {
              id
              componentProductId
              quantity
              totalLaborHours
              totalOverheadHours
              totalSetupHours
              isLabor
              isOverhead
              isSetup
              isUsage
              componentStrategyProcess {
                componentBoms {
                  edges {
                    node {
                      id
                      externalId
                      standardPackQuantity
                      standardUsage
                      componentProduct {
                        code
                      }
                    }
                  }
                }
              }
              componentStrategyProcessId
              componentProduct {
                id
                externalId
                integrationData
              }
              workOrderProcess {
                id
                externalId
                order
              }
            }
          }
        }
      }
    }
  }
  integration(where: {id: {_eq: "NetSuite"}}) {
    edges {
      node {
        id
        active
        configurationData
        integrationModels(where: {id: {_eq: "Work Order Completion"}}) {
          edges {
            node {
              id
              active
              outbound
            }
          }
        }
      }
    }
  }
}

data.transform:
$state.context.LOCAL.(
  $agg := agg;
  $cmp := $agg.components.edges.node;
  $wo := $agg.workOrder;
  $wop := $cmp[0].workOrderProcess;
  $wopStrats := $state.context.LOCAL.agg.workOrderProcess.workOrderProcessBoms.edges.node.componentProduct;
  $fg  :=  $wop.order = $string($wo.customData.ops^(operationsequence)[-1].operationsequence); /* Check if last operation */
  $op := $wo.customData.ops[$string(operationsequence)=$wop.order];
  $opid := $op.id;

  $labor := $cmp[isLabor].totalLaborHours*60;
  $overhead :=  $cmp[isOverhead].totalOverheadHours*60;
  $opDetails := $op.{
    "operationSequence": operationsequence,
    "machineResources": machineresources,
    "laborResource": laborresources,
    "laborRunTime": $labor,
    "machineRunTime": $overhead,
    "recordSetup":false,
    "laborSetupTime":0,
    "machineSetupTime":0
  };

  $asmDetails :=  $fg 
    ? {
      "quantity": $agg.quantity,
      "status":1
    } 
    : null;

  $compDetails := $count($cmp[isUsage]) > 0 ? $cmp[isUsage].(

    $phantomBoms := $filter($wopStrats, function($v) {
      $v.id = $.componentProductId
    }).strategies.edges.node.strategyProcesses.edges.node.assemblyBoms.edges.node;
    $quantity := quantity;

    $phantomBoms.{
      "quantity": $quantity  * standardUsage,
      "item":$string(componentProduct.externalId),
      "itemCode": $string(componentProduct.code),
      "inventoryDetails": [{"quantity":$quantity  * standardUsage, "status":1}]
    }
  ) : null;


  {
    "action": /*"wo_complete"*/"wo_build",
    "workOrderId":$wo.externalId,
    "workOrderDetails": {
      "startOperation":$opid~>$first(),
      "endOperation":$opid~>$last(),
      "quantity":$agg.quantity,
      "scrap":$sq,/*sq not defined in script, need to identify intent*/
      "backflush":/*$not($isNilOrEmpty($compDetails))*/true
    },
    "quantity": $agg.quantity,
    "operationDetails":$distinct($opDetails),
    "assemblyDetails":$isNilOrEmpty($asmDetails) ? null : [$asmDetails],
    "componentDetails":$isNilOrEmpty($compDetails) ? null : [$compDetails]
  };


)

